# r[impl proposal.progress]
# r[impl proposal.change]
def progress(self) -> Progress:
    """How far the code it proposes has got: proposed, written, settled."""
    proposals = [r for r in self.refs if r.kind == "proposal"]
    return Progress(
        proposed=sum(1 for r in proposals if not r.symbol or r.change),
        written=sum(1 for r in proposals if r.symbol and not r.change),
        settled=sum(1 for r in self.refs if r.settled),
    )

cli::new.text:
@main.command()
@click.argument("path")
@click.option("--title", required=True, help="Its title.")
@click.option("--prd", is_flag=True, help="A PRD: a change proposed in full, to be settled as it's made.")
def new(path: str, title: str, prd: bool) -> None:
    """Start a walkthrough at PATH (from the repository root)."""
    ctx = context()
    target = ctx.root / path
    if target.exists():
        raise click.ClickException(f"{path} exists already")
    if prd:
        from codewalk.walk.prd import template

        text = template(title)
    else:
        text = f"---\nsummary: \ntags: []\n---\n\n# {title}\n\n```walk\n```\n"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text)
    console.print(f"wrote {path}: open it with `codewalk serve`, at /edit/{path}")
